/** 包内验收清单：导出时把本次真实数量填进去，复刻/导入后逐项对。 */
export function buildAcceptanceChecklist(counts: {
  projects: number;
  presets: number;
  presetImages: number;
  characterImages: number;
  totalUniqueImages: number;
  snapshots: number;
  styleCards: number;
  trainingRecords: number;
  modesWithCards: number;
  imageGenRecords: number;
  stagedImages?: number;
}): string[] {
  const rows = [
    `布局：顶部紧凑导航条俱在（左双台切换 + 项目选择器（与项目区选择器同绑当前项目）、中步骤标签页横排且当前步有电光蓝下划线、右指引档案/生图/版本号）+ 页底更新日志（旁有打包/导入备份）；没有左侧导航栏、没有主题切换器；剧本台窗口顺序为 模式选择→基础设置→人物与大纲→剧本审查→分镜→封面生成。`,
    `主题：全站单套深空未来深色（底 #0E1116 / 面板 #161B22 / #1C2330 / 强调电光蓝 #4D7CFE / 文字浅灰三级），无可切换主题；审查页文档为 860px 深色面板。`,
    `数据：项目 ${counts.projects} 个、储存库卡 ${counts.presets} 张、图片 ${counts.totalUniqueImages} 张（内容去重后；储存库图 ${counts.presetImages}、人物图 ${counts.characterImages}，均为真实字节、无破图）、快照 ${counts.snapshots} 份、风格卡 ${counts.styleCards} 张、训练记录 ${counts.trainingRecords} 条、带基因卡模式 ${counts.modesWithCards} 个、生图记录 ${counts.imageGenRecords} 条。`,
    "模式1：基因卡八维 + 提炼摘要 + 权重（节奏 150 / 对话 125，以卡内数据为准）完整；双层时空对比规则（层内对话、禁止跨层对话）与快节奏硬标准在卡内可读。",
    "人物：储存库卡填写六项齐全（性格在详情里单独读出）；项目人物卡的来源预设标注指向新卡；同名不同人（如两位妈妈）的图片区分正确、无串图。",
    "功能抽查：打开一个项目走通 大纲→审查（时长试算有数）→分镜（两种切镜方式可选、30 秒软顶警告在）；储存库发布一张卡到项目成功；生图面板可打开但不自动提交任何任务；再点一次「打包备份」能正常下载新包。",
    "内容指纹：导入结束时工作台自动跑出的指纹核对须为全部一致（数量 / 项目大纲+剧本+快照 / 储存库卡全字段 / 基因卡全文与权重 / 图片字节，逐项哈希对上）——以核对清单里的「内容指纹」一行与逐项明细为准，有未对上先按明细定位处理，不以数量对上代替内容对上。",
    "连接：Geeknow 已在新账号重新连接（Key 没进包、没贴聊天）；核对全部通过前，旧账号不退、旧工作台不删、本地备份文件多处保存。",
  ];
  rows.splice(
    1,
    0,
    "即时复刻页（v3.79 可编辑离线功能复刻 + 页内 AI 与生图）：同一次点击下载的「复刻页」HTML 双击能离线打开（打包完成窗口里也能点「在应用内预览复刻页」直接看渲染；预览框拦截联网与本机存储，AI / 生图要在下载文件里验）——双台可切换、剧本台窗口顺序与计数一致、项目人物图与储存库卡图无破图、审查稿是 860px 文档面、审查稿人物表有内容（characterRows）；再验功能层：进编辑模式改一处台词，时长按公式重算对上；按时长打包与按剧本段切镜各切一次，超 30 秒镜头有警告清单；导出一份 SRT 与剧本格式01 能打开、时间码对上；在页顶网关填入自己的 Geeknow Key 后：读取模型列表成功、AI 填写大纲出草稿且采用前有覆盖前备份、AI 生成剧本走完规划与逐段生成（中途关掉重开能续跑）、储存库卡点「生成图片」才提交任务且出图能保存到卡；在复刻页里改一处后「导出更新后的复刻包」拿回本台导入，改动在（新增不覆盖、会多出一份副本），页内新图也在。先用它当场对照布局、内容与全部功能层，再走新账号重建。",
  );
  if ((counts.stagedImages ?? 0) > 0) {
    rows.splice(
      3,
      0,
      `生图暂存图：${counts.stagedImages} 张随包恢复——在新工作台打开生图记录，对应记录仍是已出图状态、图能打开、能保存到卡（不是已失效）。`,
    );
  }
  rows.splice(
    rows.length - 1,
    0,
    "本机状态：界面设置（储存库查看偏好 / 指引档案）随包恢复；旧台未保存的剧本草稿在新台对应项目里还在（草稿按新项目 id 重新挂接）、生图面板草稿还在。",
  );
  return rows;
}

/** 本机界面设置：随包迁移的本机键白名单（主题、储存库查看偏好、
 * 指引档案与已看状态、回归清单勾选）。剧本/预设未保存草稿不迁。 */
export const LOCAL_SETTING_KEYS = [
  "scriptbench.libraryCardSize",
  "scriptbench.libraryMouseZoom",
  "scriptbench.libraryMouseZoomScale",
  "scriptbench.guideArchive.v1",
  "scriptbench.guideSeenIds.v1",
  "scriptbench.guideArchiveSort.v1",
  "scriptbench.whatsNewSeenVersion",
  "scriptbench.regressionChecklist.v1",
] as const;

export function collectLocalSettings(): Record<string, string> {
  const out: Record<string, string> = {};
  try {
    for (const k of LOCAL_SETTING_KEYS) {
      const v = window.localStorage.getItem(k);
      // 单值过大（指引档案本机编辑异常膨胀）时跳过该键，不拖垮整包。
      if (v != null && v.length <= 200_000) out[k] = v;
    }
  } catch {
    /* 本机存储不可用：设置段留空，包内说明会写明未带设置 */
  }
  return out;
}

export function applyLocalSettings(settings: Record<string, string>): number {
  let applied = 0;
  try {
    for (const k of LOCAL_SETTING_KEYS) {
      const v = settings[k];
      if (typeof v === "string") {
        window.localStorage.setItem(k, v);
        applied += 1;
      }
    }
  } catch {
    /* 写不进就只恢复数据，设置按默认 */
  }
  return applied;
}

